typedef struct {
    int s, e, fav;
} Program;

int cmp_end(const void *a, const void *b) {
    const Program *x = (const Program *)a;
    const Program *y = (const Program *)b;
    if (x->e != y->e) return x->e - y->e;
    return x->s - y->s;
}

int cmp_start(const void *a, const void *b) {
    const Program *x = (const Program *)a;
    const Program *y = (const Program *)b;
    if (x->s != y->s) return x->s - y->s;
    return x->e - y->e;
}

int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int n, m;

    while (scanf("%d %d", &n, &m) == 2) {
        if (n == 0 && m == 0) break;

        Program *all = (Program *)malloc(sizeof(Program) * n);
        Program *fav = (Program *)malloc(sizeof(Program) * m);

        for (int i = 0; i < n; i++) {
            int h, mm;
            scanf("%d:%d", &h, &mm);
            all[i].s = h * 60 + mm;
            all[i].e = all[i].s + 30;
            all[i].fav = 0;
        }

        for (int i = 0; i < m; i++) {
            int idx;
            scanf("%d", &idx);
            idx--;
            all[idx].fav = 1;
            fav[i] = all[idx];
        }

        /* Check if favorite programs overlap */
        qsort(fav, m, sizeof(Program), cmp_start);
        int ok = 1;
        for (int i = 1; i < m; i++) {
            if (fav[i].s < fav[i - 1].e) {
                ok = 0;
                break;
            }
        }

        if (!ok) {
            printf("-1\n");
            free(all);
            free(fav);
            continue;
        }

        /* Sort all programs by end time and do interval scheduling,
           forcing all favorites to be included. */
        qsort(all, n, sizeof(Program), cmp_end);

        int ans = 0;
        int last_end = -1;

        for (int i = 0; i < n; i++) {
            if (all[i].fav) {
                if (all[i].s >= last_end) {
                    ans++;
                    last_end = all[i].e;
                }
            } else {
                if (all[i].s >= last_end) {
                    /* Safe to take only if it does not block any required favorite.
                       Since favorites are non-overlapping and must all be taken,
                       a non-favorite can be taken iff it ends before the next
                       favorite that starts after last_end, or lies between favorites.
                       Greedy by end time works if favorites are treated as mandatory picks:
                       any chosen non-favorite must not overlap future favorites. */
                    int conflict_future_fav = 0;
                    for (int j = 0; j < m; j++) {
                        if (fav[j].s >= last_end && !(all[i].e <= fav[j].s || all[i].s >= fav[j].e)) {
                            conflict_future_fav = 1;
                            break;
                        }
                    }
                    if (!conflict_future_fav) {
                        ans++;
                        last_end = all[i].e;
                    }
                }
            }
        }

        printf("%d\n", ans);

        free(all);
        free(fav);
    }

    return 0;
}

