public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            int n = Integer.parseInt(parts[0]);
            if (n == 0) break;

            int[] start = new int[n];
            int[] end = new int[n];
            boolean[] favorite = new boolean[n];

            for (int i = 0; i < n; i++) {
                String[] info = br.readLine().trim().split(" ");
                String timeStr = info[0];
                int fav = Integer.parseInt(info[1]);
                favorite[i] = (fav == 1);

                String[] hm = timeStr.split(":");
                int h = Integer.parseInt(hm[0]);
                int m = Integer.parseInt(hm[1]);
                start[i] = h * 60 + m;
                end[i] = start[i] + 30;
            }

            // Check favorite programs for conflicts
            boolean conflict = false;
            for (int i = 0; i < n; i++) {
                if (!favorite[i]) continue;
                for (int j = i + 1; j < n; j++) {
                    if (!favorite[j]) continue;
                    if (overlap(start[i], end[i], start[j], end[j])) {
                        conflict = true;
                        break;
                    }
                }
                if (conflict) break;
            }

            if (conflict) {
                System.out.println(-1);
                continue;
            }

            // Build list of non-favorite programs
            List<int[]> nonFav = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if (!favorite[i]) {
                    nonFav.add(new int[]{start[i], end[i]});
                }
            }

            // Sort non-favorite by end time
            Collections.sort(nonFav, (a, b) -> Integer.compare(a[1], b[1]));

            // Greedy selection for non-favorite programs
            int count = 0;
            int lastEnd = Integer.MIN_VALUE;

            // First count favorites (they are all non-conflicting)
            for (int i = 0; i < n; i++) {
                if (favorite[i]) count++;
            }

            // Now select compatible non-favorite programs
            for (int[] prog : nonFav) {
                if (prog[0] >= lastEnd) {
                    // Check compatibility with all favorites
                    boolean compatible = true;
                    for (int i = 0; i < n; i++) {
                        if (favorite[i]) {
                            if (overlap(prog[0], prog[1], start[i], end[i])) {
                                compatible = false;
                                break;
                            }
                        }
                    }
                    if (compatible) {
                        count++;
                        lastEnd = prog[1];
                    }
                }
            }

            System.out.println(count);
        }
    }

    private static boolean overlap(int s1, int e1, int s2, int e2) {
        return s1 < e2 && s2 < e1;
    }
}

