public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;

            Map<String, String> programToTime = new HashMap<>();
            Map<String, List<String>> timeToPrograms = new HashMap<>();

            for (int i = 0; i < n; i++) {
                String name = sc.next();
                String time = sc.next();
                programToTime.put(name, time);
                timeToPrograms.computeIfAbsent(time, k -> new ArrayList<>()).add(name);
            }

            int m = sc.nextInt();
            Set<String> favorites = new HashSet<>();
            for (int i = 0; i < m; i++) {
                favorites.add(sc.next());
            }

            // Check for conflicts among favorites
            Map<String, Integer> favoritesPerSlot = new HashMap<>();
            boolean conflict = false;
            for (String fav : favorites) {
                String time = programToTime.get(fav);
                favoritesPerSlot.merge(time, 1, Integer::sum);
                if (favoritesPerSlot.get(time) > 1) {
                    conflict = true;
                    break;
                }
            }

            if (conflict) {
                System.out.println(-1);
                continue;
            }

            // Count slots with programs but no favorites
            Set<String> favoriteSlots = new HashSet<>(favoritesPerSlot.keySet());
            int extra = 0;
            for (String time : timeToPrograms.keySet()) {
                if (!favoriteSlots.contains(time)) {
                    extra++;
                }
            }

            System.out.println(favorites.size() + extra);
        }
    }
}

