public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Interval {
        int start, end;
        boolean fav;
        Interval(int s, int e, boolean f) {
            start = s;
            end = e;
            fav = f;
        }
    }

    static int toMinute(String s) {
        String[] p = s.split(":");
        return Integer.parseInt(p[0]) * 60 + Integer.parseInt(p[1]);
    }

    static boolean overlap(Interval a, Interval b) {
        return a.start < b.end && b.start < a.end;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first;
        StringBuilder out = new StringBuilder();

        while ((first = fs.next()) != null) {
            int n = Integer.parseInt(first);
            if (n == 0) break;

            Interval[] arr = new Interval[n];
            for (int i = 0; i < n; i++) {
                String time = fs.next();
                int fav = fs.nextInt();
                int s = toMinute(time);
                int e = s + 30;
                arr[i] = new Interval(s, e, fav == 1);
            }

            List<Interval> favs = new ArrayList<>();
            for (Interval it : arr) if (it.fav) favs.add(it);

            favs.sort(Comparator.comparingInt(a -> a.start));

            boolean bad = false;
            for (int i = 1; i < favs.size(); i++) {
                if (overlap(favs.get(i - 1), favs.get(i))) {
                    bad = true;
                    break;
                }
            }

            if (bad) {
                out.append(-1).append('\n');
                continue;
            }

            List<Interval> candidates = new ArrayList<>();
            for (Interval it : arr) {
                boolean ok = true;
                if (!it.fav) {
                    for (Interval f : favs) {
                        if (overlap(it, f)) {
                            ok = false;
                            break;
                        }
                    }
                }
                if (ok) candidates.add(it);
            }

            candidates.sort((a, b) -> {
                if (a.end != b.end) return Integer.compare(a.end, b.end);
                return Integer.compare(a.start, b.start);
            });

            int ans = 0;
            int lastEnd = -1;
            for (Interval it : candidates) {
                if (it.start >= lastEnd) {
                    ans++;
                    lastEnd = it.end;
                }
            }

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}

