using namespace std;

struct Program {
    int start; // in minutes from 0:00
    int end;   // start + 30
    bool favorite;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    while (getline(cin, line)) {
        if (line.empty()) continue;
        int n;
        sscanf(line.c_str(), "%d", &n);
        if (n == 0) break;

        vector<Program> programs;
        set<int> favStarts;
        map<int, int> favCount;

        for (int i = 0; i < n; i++) {
            getline(cin, line);
            // format: hh:mm followed by space and Y or N
            int h, m;
            char favChar;
            sscanf(line.c_str(), "%d:%d %c", &h, &m, &favChar);
            int start = h * 60 + m;
            bool fav = (favChar == 'Y');
            programs.push_back({start, start + 30, fav});
            if (fav) {
                favStarts.insert(start);
                favCount[start]++;
                if (favCount[start] > 1) {
                    // duplicate favorite at same time -> impossible
                    cout << -1 << "\n";
                    goto next_dataset;
                }
            }
        }

        // Check if any two favorite programs overlap (not just same start)
        // Since duration is 30, two programs overlap if start times differ by < 30
        vector<int> favList(favStarts.begin(), favStarts.end());
        for (size_t i = 0; i + 1 < favList.size(); i++) {
            if (favList[i+1] - favList[i] < 30) {
                cout << -1 << "\n";
                goto next_dataset;
            }
        }

        // Sort all programs by start time, breaking ties by end time (but all same duration)
        sort(programs.begin(), programs.end(), [](const Program& a, const Program& b) {
            if (a.start != b.start) return a.start < b.start;
            return a.end < b.end;
        });

        // DP: dp[i] = max programs we can watch from i..n-1
        // We'll use greedy for non-favorite? Actually better: DP over intervals
        // Since n <= 1000 (typical), we can do O(n^2) DP.
        int N = n;
        vector<int> dp(N + 1, 0); // dp[i] = max from i to end
        vector<bool> mustWatch(N, false);
        for (int i = 0; i < N; i++) {
            if (programs[i].favorite) mustWatch[i] = true;
        }

        // Precompute next non-overlapping index
        vector<int> nextIdx(N, N);
        for (int i = 0; i < N; i++) {
            int j = i + 1;
            while (j < N && programs[j].start < programs[i].end) {
                j++;
            }
            nextIdx[i] = j;
        }

        // DP from right to left
        for (int i = N - 1; i >= 0; i--) {
            // Option 1: skip this program
            dp[i] = dp[i+1];
            // Option 2: take it (if favorite or optional)
            // But if it's favorite, we must take it.
            if (mustWatch[i]) {
                // must take it
                dp[i] = 1 + dp[nextIdx[i]];
            } else {
                // can choose to take or not
                dp[i] = max(dp[i], 1 + dp[nextIdx[i]]);
            }
        }

        cout << dp[0] << "\n";

        next_dataset:;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Interval {
    int s, e;
    bool fav;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    while (cin >> n >> m) {
        if (n == 0 && m == 0) break;

        vector<Interval> a;
        a.reserve(n);

        for (int i = 0; i < n; ++i) {
            int h, min30;
            cin >> h >> min30;
            int start = h * 60 + min30;
            a.push_back({start, start + 30, false});
        }

        for (int i = 0; i < m; ++i) {
            int idx;
            cin >> idx;
            --idx;                  // assume favorites are given 1-based
            if (0 <= idx && idx < n) a[idx].fav = true;
        }

        // Check favorite conflicts
        vector<Interval> favs;
        for (auto &x : a) if (x.fav) favs.push_back(x);

        sort(favs.begin(), favs.end(), [](const Interval& A, const Interval& B) {
            if (A.s != B.s) return A.s < B.s;
            return A.e < B.e;
        });

        bool bad = false;
        for (int i = 1; i < (int)favs.size(); ++i) {
            if (favs[i].s < favs[i - 1].e) {
                bad = true;
                break;
            }
        }

        if (bad) {
            cout << -1 << '\n';
            continue;
        }

        // Favorite intervals act as mandatory occupied blocks.
        // We can greedily add as many non-favorites as possible in the gaps.
        sort(a.begin(), a.end(), [](const Interval& A, const Interval& B) {
            if (A.e != B.e) return A.e < B.e;
            return A.s < B.s;
        });

        int ans = (int)favs.size();

        // Build favorite blocks with sentinels
        vector<pair<int,int>> blocks;
        blocks.push_back({-1e9, -1e9});
        for (auto &x : favs) blocks.push_back({x.s, x.e});
        blocks.push_back({1e9, 1e9});

        // For each gap between consecutive favorite programs,
        // select maximum number of non-favorites fully inside the gap.
        for (int g = 0; g + 1 < (int)blocks.size(); ++g) {
            int L = blocks[g].second;
            int R = blocks[g + 1].first;

            int lastEnd = L;
            for (auto &x : a) {
                if (x.fav) continue;
                if (x.s >= L && x.e <= R && x.s >= lastEnd) {
                    ++ans;
                    lastEnd = x.e;
                }
            }
        }

        cout << ans << '\n';
    }

    return 0;
}
